      "summary": "首页 > 科研进展 地震是地壳岩石在构造应力作用下突然破裂并释放能量的自然现象。花岗岩是大陆地壳中常见的岩石类型，其力学性质与许多天然断层围岩具有相似性，是断层摩擦研究的重要模型材料。 近日，中国科学院兰州化学物理研究所等融合宏观摩擦试验、分子动力学模拟与接触力学理论，依托花岗岩模型体系，跨尺度阐明了岩石界面摩擦的内在",
